//! Exercise logic for the Pretzel app.
//!
//! Pure functions over plain data: no storage, no I/O. The wasm bindings below are what the
//! Vue app calls; the same functions can be lifted into a server later. Values cross the
//! boundary as typed objects (`Ts<T>`), with TypeScript types generated by tsify.

pub mod checkin;
pub mod plan;
pub mod progress;
pub mod routine;

use chrono::NaiveDate;
use serde::{Deserialize, Serialize};
use tsify::{Ts, Tsify};
use wasm_bindgen::prelude::*;

use checkin::{CheckInHistory, CheckInsDue};
use plan::{PlanOptions, SessionPlan};
use progress::{CalendarMonth, ProgressSummary, SessionRecord, Slot};
use routine::Routine;

/// The core's crate version, so the app can show which build it is running.
#[wasm_bindgen(js_name = coreVersion)]
pub fn core_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

#[wasm_bindgen(js_name = defaultRoutine)]
pub fn default_routine() -> Result<Ts<Routine>, JsError> {
    Ok(routine::default_routine().into_ts()?)
}

#[wasm_bindgen(js_name = defaultPlanOptions)]
pub fn default_plan_options() -> Result<Ts<PlanOptions>, JsError> {
    Ok(PlanOptions::default().into_ts()?)
}

#[wasm_bindgen(js_name = sessionPlan)]
pub fn session_plan(
    routine: Ts<Routine>,
    options: Ts<PlanOptions>,
) -> Result<Ts<SessionPlan>, JsError> {
    Ok(plan::session_plan(&routine.to_rust()?, &options.to_rust()?).into_ts()?)
}

#[wasm_bindgen(js_name = slotForHour)]
pub fn slot_for_hour(hour: u32) -> Result<Ts<Slot>, JsError> {
    Ok(progress::slot_for_hour(hour).into_ts()?)
}

#[derive(Tsify, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ProgressInput {
    pub records: Vec<SessionRecord>,
    #[tsify(type = "string")]
    pub today: NaiveDate,
    pub routine: Routine,
}

#[wasm_bindgen(js_name = progressSummary)]
pub fn progress_summary(input: Ts<ProgressInput>) -> Result<Ts<ProgressSummary>, JsError> {
    let input = input.to_rust()?;
    Ok(progress::progress_summary(&input.records, input.today, &input.routine).into_ts()?)
}

#[derive(Tsify, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CalendarInput {
    pub records: Vec<SessionRecord>,
    pub year: i32,
    /// 1-12.
    pub month: u32,
}

#[wasm_bindgen(js_name = calendarMonth)]
pub fn calendar_month(input: Ts<CalendarInput>) -> Result<Ts<CalendarMonth>, JsError> {
    let input = input.to_rust()?;
    let month = progress::calendar_month(&input.records, input.year, input.month)
        .ok_or_else(|| JsError::new(&format!("No such month: {}-{}", input.year, input.month)))?;
    Ok(month.into_ts()?)
}

#[wasm_bindgen(js_name = checkInsDue)]
pub fn check_ins_due(history: Ts<CheckInHistory>) -> Result<Ts<CheckInsDue>, JsError> {
    Ok(checkin::check_ins_due(&history.to_rust()?).into_ts()?)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reports_the_crate_version() {
        assert_eq!(core_version(), "0.1.0");
    }
}
